import{c as a,Q as t,j as e,m as n}from"./chunks/framework.DK3sgdKX.js";const k=JSON.parse('{"title":"TH07 第五面移植说明","description":"","frontmatter":{},"headers":[],"relativePath":"TH07_STAGE5_PORT.md","filePath":"TH07_STAGE5_PORT.md","lastUpdated":1795193770000}'),i={name:"TH07_STAGE5_PORT.md"};function o(l,s,d,p,r,c){return t(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="th07-第五面移植说明" tabindex="-1">TH07 第五面移植说明 <a class="header-anchor" href="#th07-第五面移植说明" aria-label="Permalink to &quot;TH07 第五面移植说明&quot;">​</a></h1><p>本页记录以 PySTG 公开 Python API 移植东方妖妖梦（TH07）第五面的目录结构、机制映射、本地运行方式以及已知差异。移植内容位于 <code>game_content/ports/th07_stage5/</code>，完全复用现有 <code>StageManager</code>、NumPy/Numba 弹幕池、激光、道具、粒子与渲染器，不引入原版 ECL/ANM/STD 虚拟机，也不向仓库提交原作素材。</p><h2 id="_1-代码结构" tabindex="-1">1. 代码结构 <a class="header-anchor" href="#_1-代码结构" aria-label="Permalink to &quot;1. 代码结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools/import_th07_stage5_assets.py   # 离线从本地原版导出图集、音频与静态场景到本地缓存</span></span>
<span class="line"><span>tools/preview_th07_stage5.py         # 启动器，经 main.py 加载 game_content.ports.th07_stage5.entry</span></span>
<span class="line"><span>game_content/ports/th07_stage5/</span></span>
<span class="line"><span>├─ entry.py          # 标准内容入口</span></span>
<span class="line"><span>├─ stage.py          # 整面流程与 presentation_resources 加载期预热声明</span></span>
<span class="line"><span>├─ road.py           # 前后道中、幽灵入场与飞升长尾、死亡发弹</span></span>
<span class="line"><span>├─ youmu.py          # 中 Boss（2 阶段）与关底妖梦（6 阶段）、四难度分支</span></span>
<span class="line"><span>├─ common.py         # 坐标/单位换算、源 RNG 与共享发射辅助</span></span>
<span class="line"><span>├─ background.py     # 楼梯静态几何、相机轨迹、移动云组、落樱天气与 eff05 符卡底图</span></span>
<span class="line"><span>├─ titles.py         # 关卡标题与 BGM 标题演出</span></span>
<span class="line"><span>└─ resources.py      # 本地导出缓存加载与资源注册</span></span></code></pre></div><h2 id="_2-关卡流程与-boss-阶段" tabindex="-1">2. 关卡流程与 Boss 阶段 <a class="header-anchor" href="#_2-关卡流程与-boss-阶段" aria-label="Permalink to &quot;2. 关卡流程与 Boss 阶段&quot;">​</a></h2><p>关卡按原版结构依次推进：道中前半 → 中 Boss 妖梦 → 道中后半 → 关底妖梦 → 退场。关底 6 个阶段顺序如下：</p><ol><li>首非符</li><li>狱界剑「二百由旬之一闪」</li><li>第二非符</li><li>畜趣剑「无为无策之冥罚」（Easy / Normal）或 修罗剑「现世妄执」（Hard / Lunatic）</li><li>人界剑「悟入幻想」</li><li>天上剑「五衰之离别」</li></ol><p>击破、HP 阈值切卡与超时分别对应原版分支逻辑，支持 Easy / Normal / Hard / Lunatic 四难度参数。</p><h2 id="_3-原作机制如何映射到-pystg-api" tabindex="-1">3. 原作机制如何映射到 PySTG API <a class="header-anchor" href="#_3-原作机制如何映射到-pystg-api" aria-label="Permalink to &quot;3. 原作机制如何映射到 PySTG API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原作机制</th><th>PySTG 实现方式</th></tr></thead><tbody><tr><td><code>ExIns12</code> / <code>21</code> 大弹分裂</td><td>使用 <code>read_bullets</code> / <code>snapshot.select</code> + <code>create_bullets_batch</code>，无额外专用接口</td></tr><tr><td><code>ExIns13</code> 框选转弯、<code>ExIns14</code> 向自机加速</td><td>使用 <code>set_bullet_behavior</code> 的每弹数组参数（长度 <code>N</code> 或 <code>(N, 2)</code>），在共享 Numba 内核中为每颗子弹保留独立阶段参数</td></tr><tr><td><code>ExIns10</code> / <code>11</code> 斩击慢放</td><td>使用 <code>ctx.slow_motion(1/3)</code> / <code>ctx.slow_motion(1/2)</code> 与按出生代追踪的弹幕变换</td></tr><tr><td>鳞弹 / 箭弹持续朝向</td><td>使用弹幕池的 <code>render_angle_offset</code> 与 <code>render_flip_y</code> 保持转弯时的正确贴图朝向，不改变运动角</td></tr><tr><td>白色幽灵 48 节点长尾</td><td>使用 <code>ctx.attach_trail(..., history_frames=48, blend=&quot;add&quot;, hide_owner=True)</code> 的连续纹理带</td></tr><tr><td>阶梯、云层、相机与天气</td><td>离线烘焙 <code>stage5.std</code> 为 <code>SceneQuad</code>；云层使用 GPU billboard、<code>group_offsets</code> 平移 uniform、深度控制和锚点距离雾（<code>distance_alpha</code>）；落樱天气由单 Task 批量计算后写入 <code>ParticlePool(motion=&quot;manual&quot;)</code></td></tr><tr><td>天气转场震动（<code>ExIns9</code>）</td><td>使用 <code>ctx.shake_screen(frames=80, amplitude=8)</code>，仅位移游戏区视口，HUD 与边框不动</td></tr><tr><td>不可射击刀阵</td><td>通过 <code>set_interaction(collidable=False, damageable=False, interactable=False)</code> 控制</td></tr><tr><td>首次出弹/特效防卡顿</td><td>通过 <code>StageScript.presentation_resources()</code> 在加载期预热字形缓存、粒子常量表、拖尾顶点缓冲和 Numba 内核</td></tr></tbody></table><h2 id="_4-导出本地素材与运行" tabindex="-1">4. 导出本地素材与运行 <a class="header-anchor" href="#_4-导出本地素材与运行" aria-label="Permalink to &quot;4. 导出本地素材与运行&quot;">​</a></h2><p>原作图像与音频属于版权内容，需从用户本机合法持有的 TH07 1.00b 副本离线导出到本地临时目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 从本机原版导出素材到本地缓存（默认输出到系统临时目录）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/import_th07_stage5_assets.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --game-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;path-to-th07-game-dir&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --thtk-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;path-to-thtk-bin-dir&gt;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 启动第五面（默认从道中 Normal 开始）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/preview_th07_stage5.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 跳转到指定阶段与难度（--start: road | midboss | youmu；--phase 从 1 开始）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/preview_th07_stage5.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> youmu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --difficulty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lunatic</span></span></code></pre></div><p>可通过 <code>--assets &lt;目录&gt;</code> 或环境变量 <code>PYSTG_TH07_STAGE5_ASSETS</code> 指定缓存目录；缺素材时会直接报错提示，不静默替换默认贴图。</p><h2 id="_5-已知差异与未移植部分" tabindex="-1">5. 已知差异与未移植部分 <a class="header-anchor" href="#_5-已知差异与未移植部分" aria-label="Permalink to &quot;5. 已知差异与未移植部分&quot;">​</a></h2><ul><li><strong>对话（MSG）</strong>：原版人物对话与分支台词暂未移植，到达对话节点时跳过并记录日志。</li><li><strong>精细 ANM 与特效池竞争</strong>：已导出原图集并复现核心演出，但完整的 ANM 指令变换、中断和原作 400 槽特效池竞争尚未逐帧对齐。</li><li><strong>原版全局规则与自机</strong>：完整的 CherryMax / 森罗结界、原版六自机射击与 Bomb、原版计分与全部音效优先级策略尚未移植。</li><li><strong>RNG 与亚帧精度</strong>：震动使用局部确定性种子，部分视觉效果不消耗玩法共享 RNG，因此与原版录像（replay）并非逐帧等价。</li></ul>`,16)])])}const _=a(i,[["render",o]]);export{k as __pageData,_ as default};
